import Aos from 'aos';
import React, { useEffect, useState } from 'react'
import { Swiper, SwiperSlide, useSwiper } from 'swiper/react';
import 'swiper/css/effect-fade';
import { EffectFade } from 'swiper/modules';
export default function GetStarted() {
    const [swiper, setSwiper] = useState(null);
    const [currentIndex, setCurrentIndex] = useState(0);

    useEffect(function () {
        Aos.init({ duration: 2000 });
    }, []);

    const plyWoodData = [
        {
            image: 'assets/img/logo.svg',
            width:'40%'
        },
        {
            image: 'assets/img/wuudply.svg',
            width:'60%'
        }
    ]
    const goPrev = () => {
        if (swiper !== null) {
            swiper.slidePrev();
            if (currentIndex > 0) {
                setCurrentIndex(currentIndex - 1);
            }
        }
    };

    const goNext = () => {
        if (swiper !== null) {
            swiper.slideNext();
            if (currentIndex < plyWoodData.length) {
                setCurrentIndex(currentIndex + 1);
            }

        }
    };

    const d = new Date();
    let year = d.getFullYear();
    return (
        <>
            <section className="getStarted">
                <div className="container">
                    <div className="header">
                        <img src="assets/img/get-started.png" alt="" />
                    </div>
                    <div className="main__banner">
                        <h1>Better Materials.<br />Better Quality.</h1>
                    </div>
                </div>
            </section>
            <section className="our__brands">
                    <div className="container">
                        <div className="row align-items-start">
                            <div className="col-md-6">
                                <h6>Our brands</h6>
                                <h2>Crafting wood<br />into essentials that<br />make life simpler.</h2>
                            </div>
                            <div className="col-md-6">
                                <Swiper
                                    autoHeight={true}
                                    onSwiper={(s) => {
                                        setSwiper(s);
                                    }}
                                    effect={'fade'}
                                    modules={[EffectFade]}
                                >
                                    {
                                        plyWoodData.map((ele, i) => {
                                            return (
                                                <SwiperSlide key={i}>
                                                    <div className="brand__image">
                                                        <img src={ele.image} style={{width : ele.width}} alt="" />
                                                    </div>
                                                </SwiperSlide>
                                            )
                                        })
                                    }

                                </Swiper>
                                <div className="navigation">
                                    <button className={`arrow-btn ${currentIndex === 0 ? 'disabled' : ''}`} onClick={goPrev}><img src="assets/img/right-arrow.svg" alt="" /></button>
                                    <button className={`arrow-btn ${currentIndex === plyWoodData.length ? 'disabled' : ''}`} onClick={goNext}><img src="assets/img/left-arrow.svg" style={{ rotate: '180deg' }} alt="" /></button>
                                </div>
                            </div>
                        </div>
                    </div>
                </section>
                <section className="guarantee">
                    <div className="container">
                        <div className="overlay"></div>
                        <div className="col-md-10">
                        <h2>Products that are built to last, going beyond guarantee.</h2>
                        </div>
                        <div className="offset-md-6">
                            <p>For decades, Primeply Industries has been a leading manufacturer of wood and allied products in India. We're committed to excellence and constant improvement, using both advanced technology and seasoned expertise to tackle industry challenges and deliver outstanding outcomes.</p>
                            <p>Our exclusive brands, Wuudply and Primeply, symbolize premium quality and unwavering reliability. We take pride in exceed our clients' expectations, working closely with them to bring their visions to life.</p>
                        </div>


                    </div>
                </section>

                <footer className="getstarted">
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1440 320"><path fill="#000" fill-opacity="1" d="M0,224L120,213.3C240,203,480,181,720,186.7C960,192,1200,224,1320,240L1440,256L1440,320L1320,320C1200,320,960,320,720,320C480,320,240,320,120,320L0,320Z"></path></svg>
                <div className="footer__section">
                    <div className="copntainer">
                        <div className="row">
                            <div className="col-md-6">
                                <p>© {year} Primeply Industry Limited</p>
                            </div>
                        </div>
                    </div>
                </div>
                </footer>

        </>
    )
}
